INSERT INTO `job_descriptions` (`id`, `Resort_id`, `Division_id`, `Department_id`, `Position_id`, `Section_id`, `jobdescription`, `slug`, `compliance`, `reason`, `created_by`, `modified_by`, `created_at`, `updated_at`) VALUES
(17, 26, 76, 78, 146, NULL, '<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">JOB DESCRIPTION_HR Coordinator</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">JOB_METADATA</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Job_Title: HR Coordinator</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Department: Human Resources</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Location: Maldives (Resort)</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Employment_Type: Full-Time</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Reporting_To: HR Manager / Director of Human Resources</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Work_Environment: Resort Operations</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Level: Officer Level</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Contract_Type: Local or Expat</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">JOB_SUMMARY</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">Supports daily HR operations including recruitment coordination, documentation management, payroll assistance, and compliance monitoring.</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">JOB_OBJECTIVES</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Maintain employee records</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Support recruitment and onboarding</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Assist payroll processing</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Ensure compliance with Maldives Employment Act</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Support employee relations</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">ROLES_AND_RESPONSIBILITIES</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">CORE_HR_OPERATIONS</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Maintain staff files</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Update HR systems</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Track attendance</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Support payroll</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">RECRUITMENT_AND_ONBOARDING</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Schedule interviews</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Prepare documents</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Issue contracts</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Conduct induction</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">EMPLOYEE_RELATIONS</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Handle staff queries</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Maintain grievance records</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">COMPLIANCE_AND_DOCUMENT_CONTROL</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Ensure legal compliance</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Maintain disciplinary files</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Support audits</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">TRAINING_AND_DEVELOPMENT</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Arrange training</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Maintain records</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">ADMIN_SUPPORT</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Prepare HR reports</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Manage ID records</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Support HR projects</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">REQUIRED_QUALIFICATIONS</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Degree or Diploma in HR</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- 2 years HR/administration experience</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Hospitality experience preferred</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Knowledge of Maldives Employment Act</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- MS Office proficiency</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">REQUIRED_SKILLS</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">TECHNICAL_SKILLS</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- HR documentation</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Attendance systems</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Payroll support</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Reporting</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">SOFT_SKILLS</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Confidentiality</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Communication</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Organization</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Attention to detail</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">COMPETENCIES</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Accountability</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Accuracy</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Ethics</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Service orientation</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">WORK_CONDITIONS</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Resort working hours</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Weekend availability</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">PERFORMANCE_INDICATORS</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Record accuracy</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Payroll error rate</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Query resolution time</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Compliance audit success</span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">LEGAL_COMPLIANCE</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Maldives Employment Act</span></span></p>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Cambria,serif\">- Data protection</span></span></p>', 'jd-lyptvvxo', 'Rejected', NULL, 259, 259, '2025-12-08 10:29:34', '2025-12-08 10:29:34'),
(18, 26, 77, 80, 152, NULL, '<p>&nbsp;</p>\n\n<h3><strong>Job Title:&nbsp;Waitress</strong></h3>\n\n<p><strong>Location:</strong>&nbsp;[Insert Resort Name], Maldives</p>\n\n<p><strong>Job Type:</strong>&nbsp;Full-Time / Part-Time</p>\n\n<p><strong>Job Summary:</strong></p>\n\n<p>We are looking for a friendly and professional Waitress to provide excellent dining service to our guests. The ideal candidate will ensure a pleasant dining experience and maintain high standards of hospitality.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Key Responsibilities:</strong></p>\n\n<ul>\n	<li>\n	<p>Greet and seat guests politely.</p>\n	</li>\n	<li>\n	<p>Take and serve food and beverage orders accurately.</p>\n	</li>\n	<li>\n	<p>Provide menu information and answer guest queries.</p>\n	</li>\n	<li>\n	<p>Maintain cleanliness of dining area and service stations.</p>\n	</li>\n	<li>\n	<p>Collaborate with kitchen and other staff to ensure smooth operations.</p>\n	</li>\n	<li>\n	<p>Handle guest complaints or feedback professionally.</p>\n	</li>\n</ul>\n\n<p><strong>Requirements:</strong></p>\n\n<ul>\n	<li>\n	<p>Prior experience in hospitality or food service is a plus.</p>\n	</li>\n	<li>\n	<p>Good communication and interpersonal skills.</p>\n	</li>\n	<li>\n	<p>Ability to work in a team and handle busy service hours.</p>\n	</li>\n	<li>\n	<p>Presentable appearance and professional demeanor.</p>\n	</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<p><strong>Salary &amp; Benefits:</strong></p>\n\n<ul>\n	<li>\n	<p>Competitive salary (depending on experience)</p>\n	</li>\n	<li>\n	<p>Meals and staff accommodation (if applicable)</p>\n	</li>\n	<li>\n	<p>Training and development opportunities</p>\n	</li>\n</ul>\n\n<p>&nbsp;</p>', 'jd-wnfrfde6', 'Rejected', NULL, 259, 259, '2026-02-18 15:22:06', '2026-02-18 15:22:06');
