INSERT INTO `learning_programs` (`id`, `resort_id`, `name`, `description`, `objectives`, `learning_category_id`, `audience_type`, `target_audience`, `hours`, `days`, `frequency`, `delivery_mode`, `trainer`, `prior_qualification`, `created_at`, `updated_at`) VALUES
(1, 26, 'Fire Safety and Emergency Response', 'This program trains employees to respond effectively during fire incidents and other emergencies within the resort. It focuses on evacuation procedures, use of fire equipment, and emergency coordination.', '•	Understand resort emergency response procedures 	•	Identify fire hazards in the workplace 	•	Learn proper use of fire extinguishers and alarms 	•	Execute safe evacuation procedures 	•	Coord', 33, 'departments', '[\"78\",\"79\",\"80\",\"81\"]', 4.00, 1, 'annually', 'face-to-face', 187, 'None', '2026-03-10 19:41:28', '2026-03-10 19:41:28'),
(2, 26, 'Luxury Guest Service Excellence', 'This program enhances employees’ ability to deliver personalized and exceptional guest experiences aligned with luxury resort standards.', '•	Understand luxury hospitality service expectations 	•	Develop professional guest interaction skills 	•	Handle guest complaints professionally 	•	Create memorable guest experiences', 32, 'departments', '[\"80\"]', 6.00, 1, 'quarterly', 'hybrid', 187, 'Completion of Resort Orientation', '2026-03-10 19:52:26', '2026-03-10 19:52:26'),
(3, 26, 'Supervisory Skills for Hospitality Leaders', 'This program prepares supervisors and junior managers to lead teams effectively in a resort environment.', '•	Improve team leadership skills 	•	Learn task delegation techniques 	•	Handle workplace conflicts professionally 	•	Monitor employee performance', 36, 'grades', '[\"4\",\"5\"]', 8.00, 1, 'annually', 'online', 187, 'Minimum 1 year supervisory experience', '2026-03-10 19:56:15', '2026-03-10 19:56:15'),
(4, 26, 'Workplace Sexual Harassment Prevention and Awareness', 'This program educates employees about acceptable workplace behavior and legal consequences of harassment.', '•	Understand workplace harassment policies 	•	Recognize inappropriate workplace behavior 	•	Learn reporting procedures 	•	Promote a respectful workplace culture', 37, 'departments', '[\"78\",\"79\",\"80\",\"81\"]', 2.00, 1, 'annually', 'face-to-face', 187, 'None', '2026-03-10 19:57:23', '2026-03-10 19:57:23'),
(5, 26, 'Food Safety and Hygiene Standards', 'This program ensures that food handlers follow international food safety standards to protect guest health and maintain compliance with HACCP practices.', '•	Understand food contamination risks 	•	Apply safe food handling practices 	•	Maintain kitchen hygiene standards 	•	Prevent foodborne illness', 33, 'departments', '[\"80\"]', 4.00, 1, 'annually', 'face-to-face', 177, 'Basic Kitchen Safety Orientation', '2026-03-10 19:58:27', '2026-03-10 19:58:27'),
(6, 26, 'Resort Orientation and Workplace Introduction', 'Introduces new employees to the resort’s culture, policies, facilities, and operational structure.', '•	Understand company vision and values 	•	Learn resort policies and staff rules 	•	Become familiar with staff facilities and accommodation 	•	Understand reporting structure and departments', 41, 'departments', '[\"78\",\"79\",\"80\",\"81\"]', 3.00, 1, 'one-time', 'face-to-face', 188, 'None', '2026-03-10 20:02:14', '2026-03-10 20:02:14'),
(7, 26, 'HR Systems and Employee Records Management', 'Introduces HR staff to the HR system, employee records management, and internal HR procedures.', '•	Understand employee data management standards 	•	Learn HR software usage 	•	Understand payroll and attendance processes 	•	Maintain confidentiality of employee information', 35, 'departments', '[\"78\",\"79\",\"80\",\"81\"]', 3.00, 1, 'one-time', 'face-to-face', 188, 'None', '2026-03-10 20:03:48', '2026-03-10 20:03:48'),
(8, 26, 'Resort Financial Procedures and Internal Controls', 'Provides training on resort financial procedures, internal controls, and compliance standards.', '•	Understand financial approval workflows 	•	Learn resort expense policies 	•	Maintain financial record accuracy 	•	Prevent financial irregularities', 35, 'departments', '[\"79\"]', 3.00, 1, 'one-time', 'face-to-face', 171, 'None', '2026-03-10 20:04:48', '2026-03-10 20:04:48'),
(9, 26, 'Food Hygiene and Service Standards', 'Introduces F&B employees to food safety standards and service procedures required in a resort environment.', '•	Understand food hygiene standards 	•	Learn proper food handling practices 	•	Follow service standards 	•	Maintain cleanliness and guest safety', 35, 'departments', '[\"80\"]', 3.00, 1, 'one-time', 'face-to-face', 177, 'None', '2026-03-10 20:05:29', '2026-03-10 20:05:29'),
(10, 26, 'Wisdom AI® HR Software Training', 'This training program will help you to get hands-on experience with Wisdom AI HR Software.', '1. To get 80% work automatic. 2. Understand all the modules, features and function.', 38, 'departments', '[\"78\"]', 8.00, 2, 'one-time', 'face-to-face', 177, 'None', '2026-04-23 22:49:51', '2026-04-23 22:49:51');
