INSERT INTO `ta_email_templates` (`id`, `Resort_id`, `TempleteName`, `MailTemplete`, `created_at`, `updated_at`, `MailSubject`, `Placeholders`) VALUES
(1, 26, 'Selection Email Template', '<p>Dear {{candidate_name}},</p>\n\n<p>You are shortlisted for the {{interview_round}} for {{position_title}} at {{resort_name}}.</p>\n\n<p>Interview type: {{interview_type}}</p>\n\n<p>Date: {{interview_date}}</p>\n\n<p>Time: {{interview_time}}</p>\n\n<p>Link: {{interview_link}}</p>\n\n<p>Department: {{department}}</p>\n\n<p>Please confirm your availability.</p>\n\n<p>&nbsp;</p>\n\n<p>Regards,</p>\n\n<p>HR Team</p>\n\n<p>{{resort_name}}</p>', '2025-12-08 10:14:52', '2025-12-08 10:14:52', 'Selection Confirmation – {{position_title}}', '[\"candidate_name\",\"interview_round\",\"position_title\",\"resort_name\",\"interview_type\",\"interview_date\",\"interview_time\",\"interview_link\",\"department\",\"resort_name\"]'),
(2, 26, 'Rejection Email Template', '<p>Dear {{candidate_name}},</p>\n\n<p>&nbsp;</p>\n\n<p>Thank you for applying for {{position_title}} at {{resort_name}}.</p>\n\n<p>&nbsp;</p>\n\n<p>We have completed the selection process on {{completion_date}}. At this time, you were not selected.</p>\n\n<p>&nbsp;</p>\n\n<p>We wish you success in your career ahead.</p>\n\n<p>&nbsp;</p>\n\n<p>Regards,</p>\n\n<p>HR Team</p>\n\n<p>{{resort_name}}</p>', '2025-12-08 10:15:39', '2025-12-08 10:15:39', 'Update on Your Application – {{position_title}}', '[\"candidate_name\",\"position_title\",\"resort_name\",\"completion_date\",\"resort_name\"]'),
(3, 26, 'Interview Slot Selection Request', '<p>Dear {{candidate_name}},</p>\n\n<p>Thank you for your application for the position of {{position_title}} in the {{department}} at {{resort_name}}.</p>\n\n<p>We would like to proceed with the next stage of your selection process and invite you to attend an interview.</p>\n\n<p><strong>Interview Details</strong></p>\n\n<p>Interview Type: {{interview_type}}</p>\n\n<p>Interview Round: {{interview_round}}</p>\n\n<p>Date: {{interview_date}}</p>\n\n<p>Multiple time slots are available on the above date.</p>\n\n<p>Please select your preferred interview time using the link below:</p>\n\n<p>{{interview_link}}</p>\n\n<p>Kindly confirm your selected time slot at the earliest to secure your interview schedule. Once confirmed, the system will lock your selected time automatically.</p>\n\n<p>If you are unable to attend on the scheduled date, please notify us in advance so we can assist you with an alternative arrangement.</p>\n\n<p>We look forward to speaking with you.</p>\n\n<p>Best regards,</p>\n\n<p>HR Team</p>\n\n<p>{{resort_name}}</p>', '2026-02-25 18:04:51', '2026-02-25 18:04:51', 'Interview Invitation – {{position_title}} | {{resort_name}}', '[\"candidate_name\",\"position_title\",\"department\",\"resort_name\",\"interview_type\",\"interview_round\",\"interview_date\",\"interview_link\",\"resort_name\"]'),
(4, 26, 'Confirmed Interview Meeting Link', '<p>Dear {{candidate_name}},</p>\n\n<p>&nbsp;</p>\n\n<p>This is to confirm your interview for the position of {{position_title}} in the {{department}} at {{resort_name}}.</p>\n\n<p>&nbsp;</p>\n\n<p>You have selected the following schedule:</p>\n\n<p>&nbsp;</p>\n\n<p>Interview Type: {{interview_type}}</p>\n\n<p>Interview Round: {{interview_round}}</p>\n\n<p>Date: {{interview_date}}</p>\n\n<p>Time: {{interview_time}}</p>\n\n<p>&nbsp;</p>\n\n<p>Please join the interview using the meeting link below:</p>\n\n<p>&nbsp;</p>\n\n<p>{{interview_link}}</p>\n\n<p>&nbsp;</p>\n\n<p>Kindly ensure:</p>\n\n<p>&nbsp;</p>\n\n<p>&bull; You join 5 minutes before the scheduled time</p>\n\n<p>&bull; Your internet connection is stable</p>\n\n<p>&bull; Your device camera and microphone are working properly</p>\n\n<p>&bull; You are available in a quiet environment</p>\n\n<p>&nbsp;</p>\n\n<p>If you face any technical issues or are unable to attend, inform us in advance.</p>\n\n<p>&nbsp;</p>\n\n<p>We look forward to speaking with you.</p>\n\n<p>&nbsp;</p>\n\n<p>Best regards,</p>\n\n<p>HR Team</p>\n\n<p>{{resort_name}}</p>', '2026-02-25 18:23:00', '2026-02-25 18:23:00', 'Interview Confirmation – {{position_title}} | {{resort_name}}', '[\"candidate_name\",\"position_title\",\"department\",\"resort_name\",\"interview_type\",\"interview_round\",\"interview_date\",\"interview_time\",\"interview_link\",\"resort_name\"]'),
(5, 26, 'HR Round – Selected', '<p>Dear {{candidate_name}},</p>\n\n<p>Thank you for attending the HR round interview for the position of {{position_title}} with {{resort_name}}.</p>\n\n<p>We are pleased to inform you that you have successfully cleared the HR round.</p>\n\n<p>Your profile will now move to the next stage of the selection process. Our team will contact you shortly with further details regarding the upcoming round.</p>\n\n<p>We appreciate the time and effort you invested in this process and look forward to continuing the conversation.</p>\n\n<p>&nbsp;</p>\n\n<p>Best regards,</p>\n\n<p>HR Team</p>\n\n<p>{{resort_name}}</p>', '2026-03-02 14:38:46', '2026-03-04 20:19:28', 'HR Round Update – Selected for Next Stage', '[\"candidate_name\",\"position_title\",\"resort_name\",\"resort_name\"]'),
(6, 26, 'HR Round – Not Selected', '<p>Dear {{candidate_name}},</p>\n\n<p>Thank you for attending the HR round interview for the position of {{job_title}} with {{resort_name}}.</p>\n\n<p>After careful evaluation, we regret to inform you that you have not been selected to proceed to the next stage of the process.</p>\n\n<p>This was a competitive selection, and the decision does not diminish your qualifications or potential. We sincerely appreciate your interest in {{resort_name}} and the time you dedicated to the interview.</p>\n\n<p>We wish you success in your continued career journey.</p>\n\n<p>&nbsp;</p>\n\n<p>Best regards,</p>\n\n<p>HR Team</p>\n\n<p>{{resort_name}}</p>', '2026-03-02 14:39:32', '2026-03-02 14:49:25', 'Update on Your Application – {{Job_Title}}', '[\"candidate_name\",\"job_title\",\"resort_name\",\"resort_name\",\"resort_name\"]'),
(7, 26, 'HOD Round Interview Invitation', '<p>Dear {{candidate_name}},</p>\n\n<p>Thank you for successfully completing the HR round for the position of {{position_title}} at {{resort_name}}.</p>\n\n<p>We are pleased to inform you that you have been shortlisted for the next stage of the selection process, which will be the Head of Department round.</p>\n\n<p>I</p>\n\n<p>nterview Details</p>\n\n<p>Interview Type: {{interview_type}}</p>\n\n<p>Interview Round: {{interview_round}}</p>\n\n<p>Date: {{interview_date}}</p>\n\n<p>&nbsp;</p>\n\n<p>Multiple time slots are available on the above date.</p>\n\n<p>Please select your preferred interview time using the link below:</p>\n\n<p>{{interview_link}}</p>\n\n<p>Once your slot is confirmed, you will receive the interview details, including the meeting link or venue information.</p>\n\n<p>If you need any clarification, feel free to contact us.</p>\n\n<p>We look forward to your confirmation.</p>\n\n<p>Best regards,</p>\n\n<p>HR Team</p>\n\n<p>{{resort_name}}</p>', '2026-03-02 15:41:42', '2026-03-02 15:51:53', 'Next interview round – {{position_title}} | {{resort_name}}', '[\"candidate_name\",\"position_title\",\"resort_name\",\"interview_type\",\"interview_round\",\"interview_date\",\"interview_link\",\"resort_name\"]');
